<?php $page_title='Community'; require 'layout.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$pdo->prepare('DELETE FROM community_posts WHERE id=?')->execute([$id]);flash('success','Community post removed.');redirect('community.php');}
$posts=$pdo->query('SELECT p.*,u.name,u.username FROM community_posts p JOIN users u ON u.id=p.user_id ORDER BY p.created_at DESC')->fetchAll();$meetings=$pdo->query('SELECT m.*,u.name host FROM community_meetings m JOIN users u ON u.id=m.host_id ORDER BY m.starts_at DESC LIMIT 30')->fetchAll();
?><section class="admin-page-head"><div><span class="kicker">ADMIN / COMMUNITY</span><h1>Community Control</h1><p>Moderate activities and monitor community meetings.</p></div></section><div class="admin-table-card"><h2>Activity Feed</h2><div class="table-wrap"><table><thead><tr><th>Post</th><th>Author</th><th>Category</th><th>Likes</th><th>Action</th></tr></thead><tbody><?php foreach($posts as $p):?><tr><td><b><?=e($p['title'])?></b><small><?=e(time_ago($p['created_at']))?></small></td><td><?=e($p['name'])?><small>@<?=e($p['username'])?></small></td><td><?=e($p['category'])?></td><td><?=intval($p['likes'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="mini-btn danger-btn" onclick="return confirm('Remove this post?')">Remove</button></form></td></tr><?php endforeach;?></tbody></table></div></div><div class="admin-table-card"><h2>Meetings</h2><div class="table-wrap"><table><thead><tr><th>Meeting</th><th>Host</th><th>Starts</th><th>Link</th></tr></thead><tbody><?php foreach($meetings as $m):?><tr><td><?=e($m['title'])?></td><td><?=e($m['host'])?></td><td><?=e($m['starts_at'])?></td><td><a class="text-link" target="_blank" href="<?=e($m['meeting_url'])?>">Open meeting →</a></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'footer.php'; ?>
